def find_solution(a, b, n):
    """
    Find integers x and y that satisfy ax + by = n.
    Returns a tuple (x, y) or None if no solution exists.
    """
    # Special case: if both a and b are 0
    if a == 0 and b == 0:
        return (0, 0) if n == 0 else None

    # Special case: if a is 0
    if a == 0:
        if n % b == 0:
            return (0, n // b)
        return None

    # Special case: if b is 0
    if b == 0:
        if n % a == 0:
            return (n // a, 0)
        return None

    # Use Extended Euclidean Algorithm
    def extended_gcd(x, y):
        if y == 0:
            return x, 1, 0
        gcd, x1, y1 = extended_gcd(y, x % y)
        x2 = y1
        y2 = x1 - (x // y) * y1
        return gcd, x2, y2

    gcd, x0, y0 = extended_gcd(abs(a), abs(b))

    # Check if solution exists
    if n % gcd != 0:
        return None

    # Scale the solution
    x = x0 * (n // gcd)
    y = y0 * (n // gcd)

    # Adjust signs based on original a and b
    if a < 0:
        x = -x
    if b < 0:
        y = -y

